import{c as a,Q as o,j as r,m as i}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"GENEB: Why Genomic Models Are Hard to Compare","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.04525","title":"GENEB: Why Genomic Models Are Hard to Compare","archived_date":"2026-07-23T00:00:00.000Z","arxiv_id":2606.04525,"authors":["Daria Ledneva","Mikhail Nuridinov","Denis Kuznetsov"],"domain":"genomic-biological-foundation-models","published_date":"2026-06-03T00:00:00.000Z","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-07-23-geneb-genomic-model-comparability-2606-04525.md","filePath":"research/papers/2026-07-23-geneb-genomic-model-comparability-2606-04525.md","lastUpdated":1785909234000}'),t={name:"research/papers/2026-07-23-geneb-genomic-model-comparability-2606-04525.md"};function n(s,e,d,c,l,m){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="geneb-why-genomic-models-are-hard-to-compare" tabindex="-1">GENEB: Why Genomic Models Are Hard to Compare <a class="header-anchor" href="#geneb-why-genomic-models-are-hard-to-compare" aria-label="Permalink to &quot;GENEB: Why Genomic Models Are Hard to Compare&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>GENEB 是一個診斷式 benchmark，評估 40 個基因體基礎模型（genomic foundation models）在 100 個任務、13 個功能類別下的凍結表徵（frozen representations），採統一的 probing-based 協定（含 few-shot 評估情境），讓模型規模、架構、tokenization、預訓練資料等變因可被控制比較。核心論點：genomic foundation model 領域近年模型數量爆量增生，但缺乏可比的診斷式評測框架，導致各家 SOTA 宣稱難以獨立驗證——這與傳統 NLP/CV 基礎模型評測已有的標準化程度形成落差。論文透過系統性拆解各模型在不同功能類別（如調控元件辨識、變異效應預測等）上的表現差異，指出「模型架構」與「預訓練資料規模」對下游表現的貢獻並不總是符合直覺假設，部分被高度引用的模型在特定任務類別上反而遜於更簡單的基線。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p>基因體基礎模型評測方法論與 workspace 現有版圖（agent harness / LLM 工程 / GCP FinOps / SRE）完全正交；grep 核心關鍵詞（genom/biobank/biological-foundation 等）於既有 daily-topics、papers 關鍵詞集合、以及 research/NEW-DOMAINS 既探勘領域紀錄，命中皆為 0。</p>',5)])])}const b=a(t,[["render",n]]);export{h as __pageData,b as default};
